insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015300','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Para todo $x$ real, derive $f(x)=\left[\ln\left(1+e^{x^2}\right)\right]^5$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153001','00000043-0000-4000-8000-000000015300','A','$f^{\prime}(x)=\dfrac{5e^{x^2}}{1+e^{x^2}}\left[\ln\left(1+e^{x^2}\right)\right]^4$',1),('00000053-0000-4000-8000-000000153002','00000043-0000-4000-8000-000000015300','B','$f^{\prime}(x)=10xe^{x^2}\left[\ln\left(1+e^{x^2}\right)\right]^4$',2),('00000053-0000-4000-8000-000000153003','00000043-0000-4000-8000-000000015300','C','$f^{\prime}(x)=\dfrac{10xe^{x^2}}{1+e^{x^2}}\left[\ln\left(1+e^{x^2}\right)\right]^4$',3),('00000053-0000-4000-8000-000000153004','00000043-0000-4000-8000-000000015300','D','$f^{\prime}(x)=\dfrac{10x}{1+e^{x^2}}\left[\ln\left(1+e^{x^2}\right)\right]^4$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
