insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153001','00000043-0000-4000-8000-000000015300','Identifique quatro camadas: quinta potência, logaritmo, soma com exponencial e o quadrado.',1),('00000063-0000-4000-8000-000000153002','00000043-0000-4000-8000-000000015300','Derive da camada externa para a interna sem substituir o argumento por uma nova variável definitivamente.',2),('00000063-0000-4000-8000-000000153003','00000043-0000-4000-8000-000000015300','Ao chegar a $e^{x^2}$, confira se apareceu o fator $2x$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015300','$f^{\prime}(x)=\dfrac{10xe^{x^2}}{1+e^{x^2}}\left[\ln\left(1+e^{x^2}\right)\right]^4$','Escreva $u=\ln(1+e^{x^2})$; então $f=u^5$. A primeira camada fornece $f^{\prime}=5u^4u^{\prime}$. Como $u=\ln v$, com $v=1+e^{x^2}$, temos $u^{\prime}=v^{\prime}/v$. A derivada de $v$ é $e^{x^2}\cdot2x$, logo $u^{\prime}=2xe^{x^2}/(1+e^{x^2})$. Multiplicar por $5u^4$ produz o fator $10x$ e preserva todas as quatro camadas. Portanto, $f^{\prime}(x)=\dfrac{10xe^{x^2}}{1+e^{x^2}}\left[\ln\left(1+e^{x^2}\right)\right]^4$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153001','00000043-0000-4000-8000-000000015300','Mapeie as camadas','Escreva $u=\ln(1+e^{x^2})$; então $f=u^5$.',1),('00000073-0000-4000-8000-000000153002','00000043-0000-4000-8000-000000015300','Derive a potência externa','A primeira camada fornece $f^{\prime}=5u^4u^{\prime}$.',2),('00000073-0000-4000-8000-000000153003','00000043-0000-4000-8000-000000015300','Derive o logaritmo','Como $u=\ln v$, com $v=1+e^{x^2}$, temos $u^{\prime}=v^{\prime}/v$.',3),('00000073-0000-4000-8000-000000153004','00000043-0000-4000-8000-000000015300','Complete a cadeia interna','A derivada de $v$ é $e^{x^2}\cdot2x$, logo $u^{\prime}=2xe^{x^2}/(1+e^{x^2})$.',4),('00000073-0000-4000-8000-000000153005','00000043-0000-4000-8000-000000015300','Reúna e confira','Multiplicar por $5u^4$ produz o fator $10x$ e preserva todas as quatro camadas.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015301','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Determine a derivada de $g(x)=\dfrac{\sin\left((x^2+1)^3\right)}{1+x^4}$ sem expandir as potências.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153011','00000043-0000-4000-8000-000000015301','A','$g^{\prime}(x)=\dfrac{6x(x^2+1)^2\cos\left((x^2+1)^3\right)-4x^3}{(1+x^4)^2}$',1),('00000053-0000-4000-8000-000000153012','00000043-0000-4000-8000-000000015301','B','$g^{\prime}(x)=\dfrac{6x(x^2+1)^2(1+x^4)\cos\left((x^2+1)^3\right)-4x^3\sin\left((x^2+1)^3\right)}{(1+x^4)^2}$',2),('00000053-0000-4000-8000-000000153013','00000043-0000-4000-8000-000000015301','C','$g^{\prime}(x)=\dfrac{6x(x^2+1)^2\cos\left((x^2+1)^3\right)+4x^3\sin\left((x^2+1)^3\right)}{(1+x^4)^2}$',3),('00000053-0000-4000-8000-000000153014','00000043-0000-4000-8000-000000015301','D','$g^{\prime}(x)=\dfrac{3(x^2+1)^2(1+x^4)\cos\left((x^2+1)^3\right)-4x^3\sin\left((x^2+1)^3\right)}{1+x^4}$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
