insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153011','00000043-0000-4000-8000-000000015301','A estrutura externa é um quociente; trate o seno inteiro como numerador.',1),('00000063-0000-4000-8000-000000153012','00000043-0000-4000-8000-000000015301','No numerador, a regra da cadeia passa pelo seno, pela terceira potência e por $x^2+1$.',2),('00000063-0000-4000-8000-000000153013','00000043-0000-4000-8000-000000015301','Antes de concluir, confira o sinal de subtração e o quadrado do denominador.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015301','$g^{\prime}(x)=\dfrac{6x(x^2+1)^2(1+x^4)\cos\left((x^2+1)^3\right)-4x^3\sin\left((x^2+1)^3\right)}{(1+x^4)^2}$','Defina $N=\sin((x^2+1)^3)$ e $D=1+x^4$. Pela cadeia, $N^{\prime}=\cos((x^2+1)^3)\cdot3(x^2+1)^2\cdot2x$. Temos $D^{\prime}=4x^3$. Use $g^{\prime}=(N^{\prime}D-ND^{\prime})/D^2$ mantendo os fatores agrupados. O primeiro termo contém $6x(x^2+1)^2(1+x^4)$, o segundo conserva o seno, e o denominador é $(1+x^4)^2$. Portanto, $g^{\prime}(x)=\dfrac{6x(x^2+1)^2(1+x^4)\cos\left((x^2+1)^3\right)-4x^3\sin\left((x^2+1)^3\right)}{(1+x^4)^2}$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153011','00000043-0000-4000-8000-000000015301','Separe numerador e denominador','Defina $N=\sin((x^2+1)^3)$ e $D=1+x^4$.',1),('00000073-0000-4000-8000-000000153012','00000043-0000-4000-8000-000000015301','Derive o numerador','Pela cadeia, $N^{\prime}=\cos((x^2+1)^3)\cdot3(x^2+1)^2\cdot2x$.',2),('00000073-0000-4000-8000-000000153013','00000043-0000-4000-8000-000000015301','Derive o denominador','Temos $D^{\prime}=4x^3$.',3),('00000073-0000-4000-8000-000000153014','00000043-0000-4000-8000-000000015301','Aplique a regra do quociente','Use $g^{\prime}=(N^{\prime}D-ND^{\prime})/D^2$ mantendo os fatores agrupados.',4),('00000073-0000-4000-8000-000000153015','00000043-0000-4000-8000-000000015301','Verifique a estrutura','O primeiro termo contém $6x(x^2+1)^2(1+x^4)$, o segundo conserva o seno, e o denominador é $(1+x^4)^2$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015302','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Para $x>1$, seja $y=\dfrac{(x^2+1)^3\sqrt{x-1}}{e^{2x}(x+2)^4}$. Qual forma fatorada de $y^{\prime}$ resulta de diferenciação logarítmica?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153021','00000043-0000-4000-8000-000000015302','A','$y^{\prime}=y\left(\dfrac{3x}{x^2+1}+\dfrac{1}{\sqrt{x-1}}-2-\dfrac{4}{x+2}\right)$',1),('00000053-0000-4000-8000-000000153022','00000043-0000-4000-8000-000000015302','B','$y^{\prime}=y\left(\dfrac{6x}{x^2+1}+\dfrac{1}{2(x-1)}+2+\dfrac{4}{x+2}\right)$',2),('00000053-0000-4000-8000-000000153023','00000043-0000-4000-8000-000000015302','C','$y^{\prime}=\dfrac{6x}{x^2+1}+\dfrac{1}{2(x-1)}-2-\dfrac{4}{x+2}$',3),('00000053-0000-4000-8000-000000153024','00000043-0000-4000-8000-000000015302','D','$y^{\prime}=y\left(\dfrac{6x}{x^2+1}+\dfrac{1}{2(x-1)}-2-\dfrac{4}{x+2}\right)$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
