insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153021','00000043-0000-4000-8000-000000015302','O logaritmo transforma produtos em somas e fatores do denominador em termos negativos.',1),('00000063-0000-4000-8000-000000153022','00000043-0000-4000-8000-000000015302','Escreva a raiz como potência $1/2$ antes de derivar.',2),('00000063-0000-4000-8000-000000153023','00000043-0000-4000-8000-000000015302','Ao final, lembre que a derivada de $\ln y$ é $y^{\prime}/y$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015302','$y^{\prime}=y\left(\dfrac{6x}{x^2+1}+\dfrac{1}{2(x-1)}-2-\dfrac{4}{x+2}\right)$','Obtenha $\ln y=3\ln(x^2+1)+\frac12\ln(x-1)-2x-4\ln(x+2)$. A cadeia dá $3\cdot2x/(x^2+1)=6x/(x^2+1)$. Os termos restantes produzem $1/[2(x-1)]$, $-2$ e $-4/(x+2)$. Como $(\ln y)^{\prime}=y^{\prime}/y$, multiplique a soma obtida por $y$. Os fatores do denominador geram sinais negativos, e $x>1$ torna todos os logaritmos usados válidos. Portanto, $y^{\prime}=y\left(\dfrac{6x}{x^2+1}+\dfrac{1}{2(x-1)}-2-\dfrac{4}{x+2}\right)$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153021','00000043-0000-4000-8000-000000015302','Tome logaritmos','Obtenha $\ln y=3\ln(x^2+1)+\frac12\ln(x-1)-2x-4\ln(x+2)$.',1),('00000073-0000-4000-8000-000000153022','00000043-0000-4000-8000-000000015302','Derive o primeiro bloco','A cadeia dá $3\cdot2x/(x^2+1)=6x/(x^2+1)$.',2),('00000073-0000-4000-8000-000000153023','00000043-0000-4000-8000-000000015302','Derive os demais blocos','Os termos restantes produzem $1/[2(x-1)]$, $-2$ e $-4/(x+2)$.',3),('00000073-0000-4000-8000-000000153024','00000043-0000-4000-8000-000000015302','Recupere a derivada de y','Como $(\ln y)^{\prime}=y^{\prime}/y$, multiplique a soma obtida por $y$.',4),('00000073-0000-4000-8000-000000153025','00000043-0000-4000-8000-000000015302','Cheque sinais e domínio','Os fatores do denominador geram sinais negativos, e $x>1$ torna todos os logaritmos usados válidos.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015303','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','A curva $e^{xy}+x^2-y=1$ passa por $(0,0)$. Determine $y^{\prime\prime}(0)$ usando derivação implícita.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153031','00000043-0000-4000-8000-000000015303','A','$y^{\prime\prime}(0)=2$',1),('00000053-0000-4000-8000-000000153032','00000043-0000-4000-8000-000000015303','B','$y^{\prime\prime}(0)=-2$',2),('00000053-0000-4000-8000-000000153033','00000043-0000-4000-8000-000000015303','C','$y^{\prime\prime}(0)=0$',3),('00000053-0000-4000-8000-000000153034','00000043-0000-4000-8000-000000015303','D','$y^{\prime\prime}(0)=1$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
