insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015303','30000000-0000-4000-8000-000000000026',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153031','00000043-0000-4000-8000-000000015303','Na primeira derivação, o expoente $xy$ exige produto e cadeia.',1),('00000063-0000-4000-8000-000000153032','00000043-0000-4000-8000-000000015303','Calcule $y^{\prime}(0)$ antes de diferenciar novamente.',2),('00000063-0000-4000-8000-000000153033','00000043-0000-4000-8000-000000015303','Na segunda derivação, avalie no ponto somente depois de reunir todos os termos.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015303','$y^{\prime\prime}(0)=2$','A igualdade produz $e^{xy}(y+xy^{\prime})+2x-y^{\prime}=0$. Em $(0,0)$, a equação se reduz a $-y^{\prime}(0)=0$, logo $y^{\prime}(0)=0$. Para o primeiro termo, use produto: $e^{xy}(y+xy^{\prime})^2+e^{xy}(2y^{\prime}+xy^{\prime\prime})$; somam-se $2-y^{\prime\prime}$. Com $x=y=y^{\prime}=0$ e $e^0=1$, resta $2-y^{\prime\prime}(0)=0$. Assim $y^{\prime\prime}(0)=2$; o valor também é coerente com a aproximação local $y\approx x^2$. Portanto, $y^{\prime\prime}(0)=2$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153031','00000043-0000-4000-8000-000000015303','Diferencie uma vez','A igualdade produz $e^{xy}(y+xy^{\prime})+2x-y^{\prime}=0$.',1),('00000073-0000-4000-8000-000000153032','00000043-0000-4000-8000-000000015303','Avalie a primeira derivada','Em $(0,0)$, a equação se reduz a $-y^{\prime}(0)=0$, logo $y^{\prime}(0)=0$.',2),('00000073-0000-4000-8000-000000153033','00000043-0000-4000-8000-000000015303','Diferencie novamente','Para o primeiro termo, use produto: $e^{xy}(y+xy^{\prime})^2+e^{xy}(2y^{\prime}+xy^{\prime\prime})$; somam-se $2-y^{\prime\prime}$.',3),('00000073-0000-4000-8000-000000153034','00000043-0000-4000-8000-000000015303','Substitua os dados do ponto','Com $x=y=y^{\prime}=0$ e $e^0=1$, resta $2-y^{\prime\prime}(0)=0$.',4),('00000073-0000-4000-8000-000000153035','00000043-0000-4000-8000-000000015303','Resolva e verifique','Assim $y^{\prime\prime}(0)=2$; o valor também é coerente com a aproximação local $y\approx x^2$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015304','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Se $h$ é a inversa de $f(x)=x^3+x$, determine $h^{\prime\prime}(2)$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153041','00000043-0000-4000-8000-000000015304','A','$h^{\prime\prime}(2)=\dfrac{3}{32}$',1),('00000053-0000-4000-8000-000000153042','00000043-0000-4000-8000-000000015304','B','$h^{\prime\prime}(2)=-\dfrac{3}{16}$',2),('00000053-0000-4000-8000-000000153043','00000043-0000-4000-8000-000000015304','C','$h^{\prime\prime}(2)=-\dfrac{3}{32}$',3),('00000053-0000-4000-8000-000000153044','00000043-0000-4000-8000-000000015304','D','$h^{\prime\prime}(2)=-\dfrac{1}{4}$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015304','00000053-0000-4000-8000-000000153043') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015304','30000000-0000-4000-8000-000000000026',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153041','00000043-0000-4000-8000-000000015304','Primeiro encontre o número $a$ tal que $f(a)=2$.',1),('00000063-0000-4000-8000-000000153042','00000043-0000-4000-8000-000000015304','Diferencie $f(h(y))=y$ uma vez e depois outra vez.',2),('00000063-0000-4000-8000-000000153043','00000043-0000-4000-8000-000000015304','A fórmula de segunda ordem contém o cubo de $f^{\prime}(a)$ no denominador.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015304','$h^{\prime\prime}(2)=-\dfrac{3}{32}$','Como $f(1)=1^3+1=2$, temos $h(2)=1$. De $f(h(y))=y$, segue $f^{\prime}(h(y))h^{\prime}(y)=1$. A nova derivação dá $f^{\prime\prime}(h)(h^{\prime})^2+f^{\prime}(h)h^{\prime\prime}=0$. Substituindo $h^{\prime}=1/f^{\prime}(h)$, resulta $h^{\prime\prime}(y)=-f^{\prime\prime}(h(y))/[f^{\prime}(h(y))]^3$. Como $f^{\prime}(1)=4$ e $f^{\prime\prime}(1)=6$, obtemos $-6/4^3=-3/32$. Portanto, $h^{\prime\prime}(2)=-\dfrac{3}{32}$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153041','00000043-0000-4000-8000-000000015304','Localize o ponto correspondente','Como $f(1)=1^3+1=2$, temos $h(2)=1$.',1),('00000073-0000-4000-8000-000000153042','00000043-0000-4000-8000-000000015304','Obtenha a primeira derivada da inversa','De $f(h(y))=y$, segue $f^{\prime}(h(y))h^{\prime}(y)=1$.',2),('00000073-0000-4000-8000-000000153043','00000043-0000-4000-8000-000000015304','Diferencie novamente','A nova derivação dá $f^{\prime\prime}(h)(h^{\prime})^2+f^{\prime}(h)h^{\prime\prime}=0$.',3),('00000073-0000-4000-8000-000000153044','00000043-0000-4000-8000-000000015304','Isole a fórmula útil','Substituindo $h^{\prime}=1/f^{\prime}(h)$, resulta $h^{\prime\prime}(y)=-f^{\prime\prime}(h(y))/[f^{\prime}(h(y))]^3$.',4),('00000073-0000-4000-8000-000000153045','00000043-0000-4000-8000-000000015304','Avalie em y igual a 2','Como $f^{\prime}(1)=4$ e $f^{\prime\prime}(1)=6$, obtemos $-6/4^3=-3/32$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015305','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Derive $p(x)=\left[1+\sin^2\left(e^{x^3}\right)\right]^{-4}$ e mantenha a resposta fatorada.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153051','00000043-0000-4000-8000-000000015305','A','$p^{\prime}(x)=-\dfrac{8e^{x^3}\sin\left(e^{x^3}\right)\cos\left(e^{x^3}\right)}{\left[1+\sin^2\left(e^{x^3}\right)\right]^5}$',1),('00000053-0000-4000-8000-000000153052','00000043-0000-4000-8000-000000015305','B','$p^{\prime}(x)=-\dfrac{24x^2e^{x^3}\sin\left(e^{x^3}\right)\cos\left(e^{x^3}\right)}{\left[1+\sin^2\left(e^{x^3}\right)\right]^5}$',2),('00000053-0000-4000-8000-000000153053','00000043-0000-4000-8000-000000015305','C','$p^{\prime}(x)=-24x^2e^{x^3}\sin\left(e^{x^3}\right)\cos\left(e^{x^3}\right)\left[1+\sin^2\left(e^{x^3}\right)\right]^{-4}$',3),('00000053-0000-4000-8000-000000153054','00000043-0000-4000-8000-000000015305','D','$p^{\prime}(x)=-\dfrac{24x^2e^{x^3}\cos^2\left(e^{x^3}\right)}{\left[1+\sin^2\left(e^{x^3}\right)\right]^5}$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015305','00000053-0000-4000-8000-000000153052') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
