insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153051','00000043-0000-4000-8000-000000015305','Conte as camadas antes de derivar: potência negativa, soma, quadrado, seno, exponencial e cubo.',1),('00000063-0000-4000-8000-000000153052','00000043-0000-4000-8000-000000015305','A derivada de $\sin^2 u$ é $2\sin u\cos u\,u^{\prime}$.',2),('00000063-0000-4000-8000-000000153053','00000043-0000-4000-8000-000000015305','Confira o coeficiente multiplicando $-4$, $2$ e $3$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015305','$p^{\prime}(x)=-\dfrac{24x^2e^{x^3}\sin\left(e^{x^3}\right)\cos\left(e^{x^3}\right)}{\left[1+\sin^2\left(e^{x^3}\right)\right]^5}$','A primeira camada fornece $-4[1+\sin^2(e^{x^3})]^{-5}$. A derivada de $\sin^2(e^{x^3})$ é $2\sin(e^{x^3})\cos(e^{x^3})$ vezes a derivada do argumento. A derivada de $e^{x^3}$ é $e^{x^3}\cdot3x^2$. O coeficiente é $-4\cdot2\cdot3=-24$, acompanhado por $x^2e^{x^3}$. Mover a potência negativa para o denominador produz expoente $5$ e mantém cada função no argumento correto. Portanto, $p^{\prime}(x)=-\dfrac{24x^2e^{x^3}\sin\left(e^{x^3}\right)\cos\left(e^{x^3}\right)}{\left[1+\sin^2\left(e^{x^3}\right)\right]^5}$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153051','00000043-0000-4000-8000-000000015305','Derive a potência externa','A primeira camada fornece $-4[1+\sin^2(e^{x^3})]^{-5}$.',1),('00000073-0000-4000-8000-000000153052','00000043-0000-4000-8000-000000015305','Atravesse o quadrado do seno','A derivada de $\sin^2(e^{x^3})$ é $2\sin(e^{x^3})\cos(e^{x^3})$ vezes a derivada do argumento.',2),('00000073-0000-4000-8000-000000153053','00000043-0000-4000-8000-000000015305','Derive a exponencial composta','A derivada de $e^{x^3}$ é $e^{x^3}\cdot3x^2$.',3),('00000073-0000-4000-8000-000000153054','00000043-0000-4000-8000-000000015305','Multiplique os fatores','O coeficiente é $-4\cdot2\cdot3=-24$, acompanhado por $x^2e^{x^3}$.',4),('00000073-0000-4000-8000-000000153055','00000043-0000-4000-8000-000000015305','Reescreva e confira','Mover a potência negativa para o denominador produz expoente $5$ e mantém cada função no argumento correto.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015306','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Para todo $x$ real, determine a derivada de $q(x)=(x^2+1)^{\sin x}$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153061','00000043-0000-4000-8000-000000015306','A','$q^{\prime}(x)=2x\sin x\,(x^2+1)^{\sin x-1}$',1),('00000053-0000-4000-8000-000000153062','00000043-0000-4000-8000-000000015306','B','$q^{\prime}(x)=(x^2+1)^{\sin x}\cos x\ln(x^2+1)$',2),('00000053-0000-4000-8000-000000153063','00000043-0000-4000-8000-000000015306','C','$q^{\prime}(x)=(x^2+1)^{\sin x}\left[\sin x\ln(x^2+1)+\dfrac{2x\cos x}{x^2+1}\right]$',3),('00000053-0000-4000-8000-000000153064','00000043-0000-4000-8000-000000015306','D','$q^{\prime}(x)=(x^2+1)^{\sin x}\left[\cos x\ln(x^2+1)+\dfrac{2x\sin x}{x^2+1}\right]$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015306','00000053-0000-4000-8000-000000153064') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015306','30000000-0000-4000-8000-000000000026',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153061','00000043-0000-4000-8000-000000015306','A variável está simultaneamente na base e no expoente.',1),('00000063-0000-4000-8000-000000153062','00000043-0000-4000-8000-000000015306','Aplique logaritmo para transformar o expoente em fator: $\ln q=\sin x\ln(x^2+1)$.',2),('00000063-0000-4000-8000-000000153063','00000043-0000-4000-8000-000000015306','A derivada do lado esquerdo é $q^{\prime}/q$, não apenas $q^{\prime}$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015306','$q^{\prime}(x)=(x^2+1)^{\sin x}\left[\cos x\ln(x^2+1)+\dfrac{2x\sin x}{x^2+1}\right]$','Como $x^2+1>0$, escreva $\ln q=\sin x\ln(x^2+1)$. O lado esquerdo vira $q^{\prime}/q$. A derivada do lado direito é $\cos x\ln(x^2+1)+\sin x\,2x/(x^2+1)$. Multiplique a igualdade por $q=(x^2+1)^{\sin x}$. A resposta contém um termo da variação do expoente e outro da variação da base. Portanto, $q^{\prime}(x)=(x^2+1)^{\sin x}\left[\cos x\ln(x^2+1)+\dfrac{2x\sin x}{x^2+1}\right]$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153061','00000043-0000-4000-8000-000000015306','Use logaritmo','Como $x^2+1>0$, escreva $\ln q=\sin x\ln(x^2+1)$.',1),('00000073-0000-4000-8000-000000153062','00000043-0000-4000-8000-000000015306','Derive implicitamente','O lado esquerdo vira $q^{\prime}/q$.',2),('00000073-0000-4000-8000-000000153063','00000043-0000-4000-8000-000000015306','Aplique produto e cadeia','A derivada do lado direito é $\cos x\ln(x^2+1)+\sin x\,2x/(x^2+1)$.',3),('00000073-0000-4000-8000-000000153064','00000043-0000-4000-8000-000000015306','Recupere q','Multiplique a igualdade por $q=(x^2+1)^{\sin x}$.',4),('00000073-0000-4000-8000-000000153065','00000043-0000-4000-8000-000000015306','Cheque as duas dependências','A resposta contém um termo da variação do expoente e outro da variação da base.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015307','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Para todo $x$ real, simplifique a derivada de $r(x)=\ln\left[\left(x+\sqrt{1+x^2}\right)^5\right]$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153071','00000043-0000-4000-8000-000000015307','A','$r^{\prime}(x)=\dfrac{5}{\sqrt{1+x^2}}$',1),('00000053-0000-4000-8000-000000153072','00000043-0000-4000-8000-000000015307','B','$r^{\prime}(x)=\dfrac{5}{x+\sqrt{1+x^2}}$',2),('00000053-0000-4000-8000-000000153073','00000043-0000-4000-8000-000000015307','C','$r^{\prime}(x)=\dfrac{5x}{\sqrt{1+x^2}}$',3),('00000053-0000-4000-8000-000000153074','00000043-0000-4000-8000-000000015307','D','$r^{\prime}(x)=\dfrac{5\left(1+x/\sqrt{1+x^2}\right)}{\ln\left(x+\sqrt{1+x^2}\right)}$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
