insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153071','00000043-0000-4000-8000-000000015307','Interprete a expressão como $5\ln(x+\sqrt{1+x^2})$.',1),('00000063-0000-4000-8000-000000153072','00000043-0000-4000-8000-000000015307','Depois de derivar o logaritmo, aparecerá uma fração complexa.',2),('00000063-0000-4000-8000-000000153073','00000043-0000-4000-8000-000000015307','No numerador intermediário, coloque $\sqrt{1+x^2}$ em denominador comum.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015307','$r^{\prime}(x)=\dfrac{5}{\sqrt{1+x^2}}$','Como a base $x+\sqrt{1+x^2}$ é positiva, $r=5\ln(x+\sqrt{1+x^2})$. A derivada de $\sqrt{1+x^2}$ é $x/\sqrt{1+x^2}$. Temos $r^{\prime}=5[1+x/\sqrt{1+x^2}]/[x+\sqrt{1+x^2}]$. O numerador entre colchetes é $[\sqrt{1+x^2}+x]/\sqrt{1+x^2}$ e cancela com o denominador externo. Como $\sqrt{1+x^2}>|x|$, o argumento do logaritmo é positivo para todo $x$. Portanto, $r^{\prime}(x)=\dfrac{5}{\sqrt{1+x^2}}$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153071','00000043-0000-4000-8000-000000015307','Simplifique o logaritmo da potência','Como a base $x+\sqrt{1+x^2}$ é positiva, $r=5\ln(x+\sqrt{1+x^2})$.',1),('00000073-0000-4000-8000-000000153072','00000043-0000-4000-8000-000000015307','Derive a raiz','A derivada de $\sqrt{1+x^2}$ é $x/\sqrt{1+x^2}$.',2),('00000073-0000-4000-8000-000000153073','00000043-0000-4000-8000-000000015307','Aplique a regra do logaritmo','Temos $r^{\prime}=5[1+x/\sqrt{1+x^2}]/[x+\sqrt{1+x^2}]$.',3),('00000073-0000-4000-8000-000000153074','00000043-0000-4000-8000-000000015307','Reduza a fração','O numerador entre colchetes é $[\sqrt{1+x^2}+x]/\sqrt{1+x^2}$ e cancela com o denominador externo.',4),('00000073-0000-4000-8000-000000153075','00000043-0000-4000-8000-000000015307','Cheque o domínio','Como $\sqrt{1+x^2}>|x|$, o argumento do logaritmo é positivo para todo $x$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015308','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Se $F(x)=\left[\int_0^{x^2}e^{-t^2}\,dt\right]^3$, determine $F^{\prime}(x)$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153081','00000043-0000-4000-8000-000000015308','A','$F^{\prime}(x)=3e^{-x^4}\left[\int_0^{x^2}e^{-t^2}\,dt\right]^2$',1),('00000053-0000-4000-8000-000000153082','00000043-0000-4000-8000-000000015308','B','$F^{\prime}(x)=6x e^{-x^2}\left[\int_0^{x^2}e^{-t^2}\,dt\right]^2$',2),('00000053-0000-4000-8000-000000153083','00000043-0000-4000-8000-000000015308','C','$F^{\prime}(x)=6x e^{-x^4}\left[\int_0^{x^2}e^{-t^2}\,dt\right]^2$',3),('00000053-0000-4000-8000-000000153084','00000043-0000-4000-8000-000000015308','D','$F^{\prime}(x)=6x\left[\int_0^{x^2}-2t e^{-t^2}\,dt\right]^2$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015308','00000053-0000-4000-8000-000000153083') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
