insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153081','00000043-0000-4000-8000-000000015308','A potência cúbica é a camada mais externa.',1),('00000063-0000-4000-8000-000000153082','00000043-0000-4000-8000-000000015308','O Teorema Fundamental avalia a integranda no limite superior variável.',2),('00000063-0000-4000-8000-000000153083','00000043-0000-4000-8000-000000015308','Depois de substituir $t=x^2$, ainda falta derivar o próprio limite superior.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015308','$F^{\prime}(x)=6x e^{-x^4}\left[\int_0^{x^2}e^{-t^2}\,dt\right]^2$','Defina $I(x)=\int_0^{x^2}e^{-t^2}\,dt$; então $F=I^3$. Segue $F^{\prime}=3I^2I^{\prime}$. Avaliar a integranda em $t=x^2$ fornece $e^{-(x^2)^2}=e^{-x^4}$. Como $(x^2)^{\prime}=2x$, temos $I^{\prime}=2xe^{-x^4}$. Multiplicar $3I^2$ por $2xe^{-x^4}$ dá o resultado e preserva a integral não elementar. Portanto, $F^{\prime}(x)=6x e^{-x^4}\left[\int_0^{x^2}e^{-t^2}\,dt\right]^2$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153081','00000043-0000-4000-8000-000000015308','Nomeie a integral','Defina $I(x)=\int_0^{x^2}e^{-t^2}\,dt$; então $F=I^3$.',1),('00000073-0000-4000-8000-000000153082','00000043-0000-4000-8000-000000015308','Derive a potência','Segue $F^{\prime}=3I^2I^{\prime}$.',2),('00000073-0000-4000-8000-000000153083','00000043-0000-4000-8000-000000015308','Use o Teorema Fundamental','Avaliar a integranda em $t=x^2$ fornece $e^{-(x^2)^2}=e^{-x^4}$.',3),('00000073-0000-4000-8000-000000153084','00000043-0000-4000-8000-000000015308','Inclua a cadeia do limite','Como $(x^2)^{\prime}=2x$, temos $I^{\prime}=2xe^{-x^4}$.',4),('00000073-0000-4000-8000-000000153085','00000043-0000-4000-8000-000000015308','Reúna os fatores','Multiplicar $3I^2$ por $2xe^{-x^4}$ dá o resultado e preserva a integral não elementar.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015309','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Determine a derivada de $s(x)=\sqrt{1+\left[\ln(1+x^2)\right]^4}$ no domínio real.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
