insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153091','00000043-0000-4000-8000-000000015309','A raiz, a quarta potência e o logaritmo são camadas diferentes.',1),('00000063-0000-4000-8000-000000153092','00000043-0000-4000-8000-000000015309','A derivada da raiz contribui com um fator $1/(2\sqrt{\cdot})$.',2),('00000063-0000-4000-8000-000000153093','00000043-0000-4000-8000-000000015309','Os fatores numéricos $1/2$, $4$ e $2$ devem ser multiplicados.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015309','$s^{\prime}(x)=\dfrac{4x\left[\ln(1+x^2)\right]^3}{(1+x^2)\sqrt{1+\left[\ln(1+x^2)\right]^4}}$','A primeira camada é $[1+\ln^4(1+x^2)]^{1/2}$ e fornece o fator $1/[2\sqrt{1+\ln^4(1+x^2)}]$. A próxima camada contribui com $4[\ln(1+x^2)]^3$. A derivada de $\ln(1+x^2)$ é $2x/(1+x^2)$. O produto $(1/2)\cdot4\cdot2x$ reduz-se a $4x$. Como $1+x^2>0$ e o radicando externo é pelo menos 1, a fórmula vale para todo $x$ real. Portanto, $s^{\prime}(x)=\dfrac{4x\left[\ln(1+x^2)\right]^3}{(1+x^2)\sqrt{1+\left[\ln(1+x^2)\right]^4}}$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153091','00000043-0000-4000-8000-000000015309','Derive a raiz externa','A primeira camada é $[1+\ln^4(1+x^2)]^{1/2}$ e fornece o fator $1/[2\sqrt{1+\ln^4(1+x^2)}]$.',1),('00000073-0000-4000-8000-000000153092','00000043-0000-4000-8000-000000015309','Derive a quarta potência','A próxima camada contribui com $4[\ln(1+x^2)]^3$.',2),('00000073-0000-4000-8000-000000153093','00000043-0000-4000-8000-000000015309','Derive o logaritmo','A derivada de $\ln(1+x^2)$ é $2x/(1+x^2)$.',3),('00000073-0000-4000-8000-000000153094','00000043-0000-4000-8000-000000015309','Simplifique os coeficientes','O produto $(1/2)\cdot4\cdot2x$ reduz-se a $4x$.',4),('00000073-0000-4000-8000-000000153095','00000043-0000-4000-8000-000000015309','Confira domínio e estrutura','Como $1+x^2>0$ e o radicando externo é pelo menos 1, a fórmula vale para todo $x$ real.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015310','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Calcule $\lim_{x\to0}\dfrac{\sqrt{1+3x}-\sqrt{1-x}-2x}{x^2}$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
