insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153101','00000043-0000-4000-8000-000000015310','A substituição produz $0/0$, mas o cancelamento dos termos lineares exige informação de segunda ordem.',1),('00000063-0000-4000-8000-000000153102','00000043-0000-4000-8000-000000015310','L’Hôpital pode ser aplicada e a primeira razão ainda terá forma $0/0$.',2),('00000063-0000-4000-8000-000000153103','00000043-0000-4000-8000-000000015310','Na segunda derivação, use $\dfrac{d}{dx}(1+ax)^{-1/2}=-\dfrac a2(1+ax)^{-3/2}$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015310','$-1$','Em $x=0$, numerador e denominador são zero. A nova razão é $[3/(2\sqrt{1+3x})+1/(2\sqrt{1-x})-2]/(2x)$, ainda $0/0$. O numerador passa a $-9/[4(1+3x)^{3/2}]+1/[4(1-x)^{3/2}]$, e o denominador vira $2$. O quociente vale $(-9/4+1/4)/2=(-2)/2$. As duas aplicações são válidas nas vizinhanças consideradas e o limite é $-1$. Portanto, $-1$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153101','00000043-0000-4000-8000-000000015310','Confirme a indeterminação','Em $x=0$, numerador e denominador são zero.',1),('00000073-0000-4000-8000-000000153102','00000043-0000-4000-8000-000000015310','Aplique L’Hôpital uma vez','A nova razão é $[3/(2\sqrt{1+3x})+1/(2\sqrt{1-x})-2]/(2x)$, ainda $0/0$.',2),('00000073-0000-4000-8000-000000153103','00000043-0000-4000-8000-000000015310','Derive novamente','O numerador passa a $-9/[4(1+3x)^{3/2}]+1/[4(1-x)^{3/2}]$, e o denominador vira $2$.',3),('00000073-0000-4000-8000-000000153104','00000043-0000-4000-8000-000000015310','Avalie em zero','O quociente vale $(-9/4+1/4)/2=(-2)/2$.',4),('00000073-0000-4000-8000-000000153105','00000043-0000-4000-8000-000000015310','Conclua','As duas aplicações são válidas nas vizinhanças consideradas e o limite é $-1$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015311','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Calcule $\lim_{x\to\infty}x\left(\sqrt{x^2+5x+4}-x-\dfrac52\right)$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
