insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153111','00000043-0000-4000-8000-000000015311','A subtração remove tanto o termo dominante quanto o termo constante da raiz.',1),('00000063-0000-4000-8000-000000153112','00000043-0000-4000-8000-000000015311','Racionalize primeiro $\sqrt{x^2+5x+4}-x$ e depois isole a diferença em relação a $5/2$.',2),('00000063-0000-4000-8000-000000153113','00000043-0000-4000-8000-000000015311','Após colocar a nova diferença em uma única fração, racionalize a expressão que ainda tende a zero.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015311','$-\dfrac98$','Temos $\sqrt{x^2+5x+4}-x=(5x+4)/(\sqrt{x^2+5x+4}+x)$. A diferença vira $[8-5(\sqrt{x^2+5x+4}-x)]/[2(\sqrt{x^2+5x+4}+x)]$. Se $d=\sqrt{x^2+5x+4}-x$, então a expressão total é $[(8-5d)/2]\,x/(\sqrt{x^2+5x+4}+x)$. A racionalização mostra $d\to5/2$, enquanto dividir o segundo fator por $x$ mostra $x/(\sqrt{x^2+5x+4}+x)\to1/2$. O produto tende a $[(8-25/2)/2](1/2)=(-9/4)(1/2)=-9/8$. Portanto, $-\dfrac98$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153111','00000043-0000-4000-8000-000000015311','Racionalize a primeira diferença','Temos $\sqrt{x^2+5x+4}-x=(5x+4)/(\sqrt{x^2+5x+4}+x)$.',1),('00000073-0000-4000-8000-000000153112','00000043-0000-4000-8000-000000015311','Subtraia cinco meios','A diferença vira $[8-5(\sqrt{x^2+5x+4}-x)]/[2(\sqrt{x^2+5x+4}+x)]$.',2),('00000073-0000-4000-8000-000000153113','00000043-0000-4000-8000-000000015311','Separe os fatores com limite','Se $d=\sqrt{x^2+5x+4}-x$, então a expressão total é $[(8-5d)/2]\,x/(\sqrt{x^2+5x+4}+x)$.',3),('00000073-0000-4000-8000-000000153114','00000043-0000-4000-8000-000000015311','Calcule os dois limites auxiliares','A racionalização mostra $d\to5/2$, enquanto dividir o segundo fator por $x$ mostra $x/(\sqrt{x^2+5x+4}+x)\to1/2$.',4),('00000073-0000-4000-8000-000000153115','00000043-0000-4000-8000-000000015311','Combine os resultados','O produto tende a $[(8-25/2)/2](1/2)=(-9/4)(1/2)=-9/8$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015312','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Use L’Hôpital, verificando a indeterminação em cada etapa, para calcular $\lim_{x\to0}\dfrac{e^{x^2}-\cos x}{x^2}$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
