insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153121','00000043-0000-4000-8000-000000015312','A primeira substituição é $0/0$.',1),('00000063-0000-4000-8000-000000153122','00000043-0000-4000-8000-000000015312','Depois da primeira derivação, a razão continua indeterminada.',2),('00000063-0000-4000-8000-000000153123','00000043-0000-4000-8000-000000015312','Na derivada de $2xe^{x^2}$, use produto e cadeia.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015312','$\dfrac32$','Em zero, $e^{x^2}-\cos x=1-1=0$ e $x^2=0$. Obtemos $[2xe^{x^2}+\sin x]/(2x)$, que ainda é $0/0$. A razão passa a $[2e^{x^2}+4x^2e^{x^2}+\cos x]/2$. Em $x=0$, o numerador vale $2+0+1=3$. O limite é $3/2$, coerente com contribuições quadráticas $x^2$ e $x^2/2$. Portanto, $\dfrac32$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153121','00000043-0000-4000-8000-000000015312','Teste a forma inicial','Em zero, $e^{x^2}-\cos x=1-1=0$ e $x^2=0$.',1),('00000073-0000-4000-8000-000000153122','00000043-0000-4000-8000-000000015312','Aplique a primeira vez','Obtemos $[2xe^{x^2}+\sin x]/(2x)$, que ainda é $0/0$.',2),('00000073-0000-4000-8000-000000153123','00000043-0000-4000-8000-000000015312','Derive uma segunda vez','A razão passa a $[2e^{x^2}+4x^2e^{x^2}+\cos x]/2$.',3),('00000073-0000-4000-8000-000000153124','00000043-0000-4000-8000-000000015312','Avalie o novo quociente','Em $x=0$, o numerador vale $2+0+1=3$.',4),('00000073-0000-4000-8000-000000153125','00000043-0000-4000-8000-000000015312','Conclua e confira','O limite é $3/2$, coerente com contribuições quadráticas $x^2$ e $x^2/2$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015313','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Calcule $\lim_{x\to0}\dfrac{\ln(1+x)-x+x^2/2}{x^3}$ por aplicações sucessivas de L’Hôpital.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
