insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153131','00000043-0000-4000-8000-000000015313','Os termos de primeira e segunda ordem foram escolhidos para cancelar.',1),('00000063-0000-4000-8000-000000153132','00000043-0000-4000-8000-000000015313','A forma $0/0$ persiste depois das duas primeiras derivações.',2),('00000063-0000-4000-8000-000000153133','00000043-0000-4000-8000-000000015313','Na terceira etapa, simplifique a derivada de $-1/(1+x)^2$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015313','$\dfrac13$','Substituir zero produz $0/0$. A razão torna-se $[1/(1+x)-1+x]/(3x^2)$, ainda $0/0$. Obtemos $[-1/(1+x)^2+1]/(6x)$, novamente $0/0$. A razão final é $[2/(1+x)^3]/6$. Em zero resulta $2/6=1/3$; o cálculo identifica o primeiro termo não cancelado. Portanto, $\dfrac13$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153131','00000043-0000-4000-8000-000000015313','Verifique a forma','Substituir zero produz $0/0$.',1),('00000073-0000-4000-8000-000000153132','00000043-0000-4000-8000-000000015313','Derive uma vez','A razão torna-se $[1/(1+x)-1+x]/(3x^2)$, ainda $0/0$.',2),('00000073-0000-4000-8000-000000153133','00000043-0000-4000-8000-000000015313','Derive duas vezes','Obtemos $[-1/(1+x)^2+1]/(6x)$, novamente $0/0$.',3),('00000073-0000-4000-8000-000000153134','00000043-0000-4000-8000-000000015313','Aplique pela terceira vez','A razão final é $[2/(1+x)^3]/6$.',4),('00000073-0000-4000-8000-000000153135','00000043-0000-4000-8000-000000015313','Avalie e interprete','Em zero resulta $2/6=1/3$; o cálculo identifica o primeiro termo não cancelado.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
