insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153141','00000043-0000-4000-8000-000000015314','A','$\dfrac18$',1),('00000053-0000-4000-8000-000000153142','00000043-0000-4000-8000-000000015314','B','$\dfrac12$',2),('00000053-0000-4000-8000-000000153143','00000043-0000-4000-8000-000000015314','C','$0$',3),('00000053-0000-4000-8000-000000153144','00000043-0000-4000-8000-000000015314','D','$-\dfrac18$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
