insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015314','30000000-0000-4000-8000-000000000020',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153141','00000043-0000-4000-8000-000000015314','A subtração remove os termos constante e de ordem $1/x^2$.',1),('00000063-0000-4000-8000-000000153142','00000043-0000-4000-8000-000000015314','Faça $u=1/x^2$ para transformar o problema em um limite quando $u\to0^+$.',2),('00000063-0000-4000-8000-000000153143','00000043-0000-4000-8000-000000015314','Depois de uma racionalização, ainda será necessário analisar um quociente de primeira ordem em $u$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015314','$-\dfrac18$','Com $u=1/x^2$, o limite vira $[\sqrt{1+u}-1-u/2]/u^2$ quando $u\to0^+$. Use $\sqrt{1+u}-1=u/(\sqrt{1+u}+1)$. A expressão reduz-se a $[1/(\sqrt{1+u}+1)-1/2]/u$. O numerador é $(1-\sqrt{1+u})/[2(\sqrt{1+u}+1)]=-u/[2(\sqrt{1+u}+1)^2]$. Após cancelar $u$, resta $-1/[2(\sqrt{1+u}+1)^2]$, cujo limite é $-1/8$. Portanto, $-\dfrac18$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153141','00000043-0000-4000-8000-000000015314','Troque a variável pequena','Com $u=1/x^2$, o limite vira $[\sqrt{1+u}-1-u/2]/u^2$ quando $u\to0^+$.',1),('00000073-0000-4000-8000-000000153142','00000043-0000-4000-8000-000000015314','Racionalize a raiz','Use $\sqrt{1+u}-1=u/(\sqrt{1+u}+1)$.',2),('00000073-0000-4000-8000-000000153143','00000043-0000-4000-8000-000000015314','Coloque em uma fração','A expressão reduz-se a $[1/(\sqrt{1+u}+1)-1/2]/u$.',3),('00000073-0000-4000-8000-000000153144','00000043-0000-4000-8000-000000015314','Racionalize a nova diferença','O numerador é $(1-\sqrt{1+u})/[2(\sqrt{1+u}+1)]=-u/[2(\sqrt{1+u}+1)^2]$.',4),('00000073-0000-4000-8000-000000153145','00000043-0000-4000-8000-000000015314','Cancele e avalie','Após cancelar $u$, resta $-1/[2(\sqrt{1+u}+1)^2]$, cujo limite é $-1/8$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015315','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Calcule $\lim_{x\to0^+}x^x$ transformando a potência indeterminada antes de usar L’Hôpital.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
