insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153151','00000043-0000-4000-8000-000000015315','A forma $0^0$ não permite aplicar L’Hôpital diretamente.',1),('00000063-0000-4000-8000-000000153152','00000043-0000-4000-8000-000000015315','Defina $y=x^x$ e tome logaritmo: $\ln y=x\ln x$.',2),('00000063-0000-4000-8000-000000153153','00000043-0000-4000-8000-000000015315','Reescreva $x\ln x$ como um quociente para obter uma forma apropriada.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015315','$1$','Quando $x\to0^+$, base e expoente tendem a zero, produzindo a forma indeterminada $0^0$. Se $y=x^x$, então $\ln y=x\ln x=\ln x/(1/x)$. A razão é $(-\infty)/(\infty)$ e sua derivada dá $(1/x)/(-1/x^2)=-x$. Assim $\lim\ln y=0$. Pela continuidade de $e^u$, segue $\lim y=e^0=1$. Portanto, $1$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153151','00000043-0000-4000-8000-000000015315','Reconheça a forma','Quando $x\to0^+$, base e expoente tendem a zero, produzindo a forma indeterminada $0^0$.',1),('00000073-0000-4000-8000-000000153152','00000043-0000-4000-8000-000000015315','Linearize com logaritmo','Se $y=x^x$, então $\ln y=x\ln x=\ln x/(1/x)$.',2),('00000073-0000-4000-8000-000000153153','00000043-0000-4000-8000-000000015315','Aplique L’Hôpital ao logaritmo','A razão é $(-\infty)/(\infty)$ e sua derivada dá $(1/x)/(-1/x^2)=-x$.',3),('00000073-0000-4000-8000-000000153154','00000043-0000-4000-8000-000000015315','Tome o limite transformado','Assim $\lim\ln y=0$.',4),('00000073-0000-4000-8000-000000153155','00000043-0000-4000-8000-000000015315','Volte pela exponencial','Pela continuidade de $e^u$, segue $\lim y=e^0=1$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015316','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Determine $\lim_{x\to\infty}\left(1+\dfrac3x\right)^{2x}$ justificando a transformação da forma $1^{\infty}$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153161','00000043-0000-4000-8000-000000015316','A','$e^3$',1),('00000053-0000-4000-8000-000000153162','00000043-0000-4000-8000-000000015316','B','$6e$',2),('00000053-0000-4000-8000-000000153163','00000043-0000-4000-8000-000000015316','C','$e^6$',3),('00000053-0000-4000-8000-000000153164','00000043-0000-4000-8000-000000015316','D','$1$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
