insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153161','00000043-0000-4000-8000-000000015316','Tome logaritmo antes de manipular o expoente variável.',1),('00000063-0000-4000-8000-000000153162','00000043-0000-4000-8000-000000015316','Escreva $2x\ln(1+3/x)$ como um quociente que tende a $0/0$.',2),('00000063-0000-4000-8000-000000153163','00000043-0000-4000-8000-000000015316','Calcule primeiro o limite do logaritmo e só então aplique a exponencial.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015316','$e^6$','Defina $y=(1+3/x)^{2x}$; então $\ln y=2x\ln(1+3/x)$. Escreva $\ln y=2\ln(1+3/x)/(1/x)$, uma forma $0/0$. As derivadas dão $2[-3/(x^2(1+3/x))]/(-1/x^2)=6/(1+3/x)$. Quando $x\to\infty$, essa expressão tende a $6$. Logo $y$ tende a $e^6$, não a 1; o expoente amplifica a pequena variação da base. Portanto, $e^6$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153161','00000043-0000-4000-8000-000000015316','Nomeie a potência','Defina $y=(1+3/x)^{2x}$; então $\ln y=2x\ln(1+3/x)$.',1),('00000073-0000-4000-8000-000000153162','00000043-0000-4000-8000-000000015316','Crie um quociente','Escreva $\ln y=2\ln(1+3/x)/(1/x)$, uma forma $0/0$.',2),('00000073-0000-4000-8000-000000153163','00000043-0000-4000-8000-000000015316','Aplique L’Hôpital','As derivadas dão $2[-3/(x^2(1+3/x))]/(-1/x^2)=6/(1+3/x)$.',3),('00000073-0000-4000-8000-000000153164','00000043-0000-4000-8000-000000015316','Avalie o logaritmo','Quando $x\to\infty$, essa expressão tende a $6$.',4),('00000073-0000-4000-8000-000000153165','00000043-0000-4000-8000-000000015316','Desfaça a transformação','Logo $y$ tende a $e^6$, não a 1; o expoente amplifica a pequena variação da base.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
