insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153171','00000043-0000-4000-8000-000000015317','A forma inicial é $0/0$ e os termos lineares das duas funções se cancelam.',1),('00000063-0000-4000-8000-000000153172','00000043-0000-4000-8000-000000015317','Depois da primeira e da segunda aplicação, a avaliação em zero ainda produz $0/0$.',2),('00000063-0000-4000-8000-000000153173','00000043-0000-4000-8000-000000015317','Na terceira derivação, use $(\sec^2x)^{\prime}=2\sec^2x\tan x$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015317','$\dfrac12$','Numerador e denominador valem zero em $x=0$. A razão vira $(\sec^2x-\cos x)/(3x^2)$ e continua $0/0$. Obtemos $(2\sec^2x\tan x+\sin x)/(6x)$, ainda $0/0$. O numerador passa a $4\sec^2x\tan^2x+2\sec^4x+\cos x$, e o denominador a $6$. Como $\tan0=0$, $\sec0=1$ e $\cos0=1$, resulta $(0+2+1)/6=1/2$. Portanto, $\dfrac12$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153171','00000043-0000-4000-8000-000000015317','Confirme a forma inicial','Numerador e denominador valem zero em $x=0$.',1),('00000073-0000-4000-8000-000000153172','00000043-0000-4000-8000-000000015317','Derive uma vez','A razão vira $(\sec^2x-\cos x)/(3x^2)$ e continua $0/0$.',2),('00000073-0000-4000-8000-000000153173','00000043-0000-4000-8000-000000015317','Derive uma segunda vez','Obtemos $(2\sec^2x\tan x+\sin x)/(6x)$, ainda $0/0$.',3),('00000073-0000-4000-8000-000000153174','00000043-0000-4000-8000-000000015317','Derive pela terceira vez','O numerador passa a $4\sec^2x\tan^2x+2\sec^4x+\cos x$, e o denominador a $6$.',4),('00000073-0000-4000-8000-000000153175','00000043-0000-4000-8000-000000015317','Avalie em zero','Como $\tan0=0$, $\sec0=1$ e $\cos0=1$, resulta $(0+2+1)/6=1/2$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015318','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Calcule $\lim_{x\to\infty}x\left[\ln(x+1)-\ln x\right]$ sem separar incorretamente o produto de limites.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
