insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153181','00000043-0000-4000-8000-000000015318','A expressão tem a forma $\infty\cdot0$; combine primeiro os logaritmos.',1),('00000063-0000-4000-8000-000000153182','00000043-0000-4000-8000-000000015318','Depois escreva o produto como um quociente apropriado para L’Hôpital.',2),('00000063-0000-4000-8000-000000153183','00000043-0000-4000-8000-000000015318','A derivada de $\ln(1+1/x)$ contém um fator $-1/x^2$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015318','$1$','A diferença é $\ln((x+1)/x)=\ln(1+1/x)$. Escreva $x\ln(1+1/x)=\ln(1+1/x)/(1/x)$, uma forma $0/0$. A razão das derivadas é $[-1/(x^2(1+1/x))]/(-1/x^2)$. O quociente reduz-se a $1/(1+1/x)$. No infinito o valor tende a 1; o fator $x$ compensa exatamente a pequena diferença logarítmica. Portanto, $1$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153181','00000043-0000-4000-8000-000000015318','Combine os logaritmos','A diferença é $\ln((x+1)/x)=\ln(1+1/x)$.',1),('00000073-0000-4000-8000-000000153182','00000043-0000-4000-8000-000000015318','Converta o produto','Escreva $x\ln(1+1/x)=\ln(1+1/x)/(1/x)$, uma forma $0/0$.',2),('00000073-0000-4000-8000-000000153183','00000043-0000-4000-8000-000000015318','Aplique L’Hôpital','A razão das derivadas é $[-1/(x^2(1+1/x))]/(-1/x^2)$.',3),('00000073-0000-4000-8000-000000153184','00000043-0000-4000-8000-000000015318','Simplifique','O quociente reduz-se a $1/(1+1/x)$.',4),('00000073-0000-4000-8000-000000153185','00000043-0000-4000-8000-000000015318','Avalie e interprete','No infinito o valor tende a 1; o fator $x$ compensa exatamente a pequena diferença logarítmica.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015319','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001503','multiple_choice','hard','published','Determine $\lim_{x\to0}\dfrac{\sqrt{1+\sin x}-\sqrt{1-\sin x}-x}{x^3}$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000153191','00000043-0000-4000-8000-000000015319','A','$-\dfrac1{24}$',1),('00000053-0000-4000-8000-000000153192','00000043-0000-4000-8000-000000015319','B','$\dfrac1{24}$',2),('00000053-0000-4000-8000-000000153193','00000043-0000-4000-8000-000000015319','C','$-\dfrac16$',3),('00000053-0000-4000-8000-000000153194','00000043-0000-4000-8000-000000015319','D','$0$',4) on conflict (id) do update set label=excluded.label,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
