insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015319','30000000-0000-4000-8000-000000000031',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000153191','00000043-0000-4000-8000-000000015319','A diferença das raízes tem o mesmo termo linear que $x$, por isso o numerador cancela até ordem alta.',1),('00000063-0000-4000-8000-000000153192','00000043-0000-4000-8000-000000015319','Racionalize a diferença das duas raízes antes de decidir entre novas simplificações e L’Hôpital.',2),('00000063-0000-4000-8000-000000153193','00000043-0000-4000-8000-000000015319','Uma verificação eficiente usa os termos até grau três de $\sin x$ e de $\sqrt{1+u}$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015319','$-\dfrac1{24}$','Temos $\sqrt{1+\sin x}-\sqrt{1-\sin x}=2\sin x/[\sqrt{1+\sin x}+\sqrt{1-\sin x}]$. O denominador da fração racionalizada tende a 2, então o termo linear é $x$ e é cancelado no enunciado. Usando $\sqrt{1+u}-\sqrt{1-u}=u+u^3/8+o(u^3)$, com $u=\sin x$, obtemos a estrutura cúbica necessária. Como $\sin x=x-x^3/6+o(x^3)$ e $(\sin x)^3=x^3+o(x^3)$, a diferença das raízes é $x-x^3/24+o(x^3)$. Subtrair $x$ e dividir por $x^3$ deixa $-1/24+o(1)$, logo o limite é $-1/24$. Portanto, $-\dfrac1{24}$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000153191','00000043-0000-4000-8000-000000015319','Racionalize a diferença','Temos $\sqrt{1+\sin x}-\sqrt{1-\sin x}=2\sin x/[\sqrt{1+\sin x}+\sqrt{1-\sin x}]$.',1),('00000073-0000-4000-8000-000000153192','00000043-0000-4000-8000-000000015319','Identifique a ordem necessária','O denominador da fração racionalizada tende a 2, então o termo linear é $x$ e é cancelado no enunciado.',2),('00000073-0000-4000-8000-000000153193','00000043-0000-4000-8000-000000015319','Expanda apenas para conferência local','Usando $\sqrt{1+u}-\sqrt{1-u}=u+u^3/8+o(u^3)$, com $u=\sin x$, obtemos a estrutura cúbica necessária.',3),('00000073-0000-4000-8000-000000153194','00000043-0000-4000-8000-000000015319','Substitua o seno','Como $\sin x=x-x^3/6+o(x^3)$ e $(\sin x)^3=x^3+o(x^3)$, a diferença das raízes é $x-x^3/24+o(x^3)$.',4),('00000073-0000-4000-8000-000000153195','00000043-0000-4000-8000-000000015319','Divida e conclua','Subtrair $x$ e dividir por $x^3$ deixa $-1/24+o(1)$, logo o limite é $-1/24$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
